using System.Data;using Karaoke.DAL;using Karaoke.DTO;namespace Karaoke.BUS;public class KaraokeService{readonly KaraokeRepository r=new();public DataTable Rooms()=>r.Rooms();public DataTable Services()=>r.Services();public DataTable ActiveBills()=>r.ActiveBills();public DataTable BillServices(int id)=>r.BillServices(id);public int OpenRoom(int id)=>r.OpenRoom(id);public void AddServices(int id,List<ServiceItem> items){if(items.Count==0||items.Any(x=>x.SoLuong<=0))throw new ArgumentException("Chọn dịch vụ và số lượng hợp lệ.");r.AddServices(id,items);}public void Pay(int id)=>r.Pay(id);}